  const request: ListSessionsMessage = {type: 'list_sessions'};

  if (message.limit !== undefined && !isNonNegativeInteger(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  if (message.limit !== undefined) request.limit = message.limit as number;

  const before = message.before === undefined ? undefined : validateCursor(message.before);
  if (message.before !== undefined && !before) {
    return {valid: false, error: 'list_sessions before must be a cursor with a sessionId and a valid updatedAt'};
  }
  if (before) request.before = before;

  return {valid: true, data: request};
}

function isNonNegativeInteger(value: unknown): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0;
}

function validateCursor(raw: unknown): SessionCursor | undefined {
  if (typeof raw !== 'object' || raw === null) return undefined;
  const {updatedAt, sessionId} = raw as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH)
    return undefined;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return undefined;
  if (!Number.isFinite(new Date(updatedAt).getTime())) return undefined;
  return {updatedAt, sessionId};
}
